mcp:tool-listener.mcp:parameters-schema:
{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"origen": {
			"type": "string",
			"description": "Aeropuerto de origen: código IATA (3 letras, p. ej. MAD) o nombre de la ciudad/aeropuerto"
		},
		"destino": {
			"type": "string",
			"description": "Aeropuerto de destino: código IATA (3 letras, p. ej. MAD) o nombre de la ciudad/aeropuerto"
		},
		"fecha": {
			"type": "string",
			"description": "Fecha del vuelo en formato AAAA-MM-DD"
		},
		"pasajeros": {
			"type": "integer",
			"minimum": 1,
			"maximum": 9,
			"description": "Número de pasajeros (1 por defecto)"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"origen",
		"destino",
		"fecha"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"vueloId": {
			"type": "string",
			"description": "Identificador del vuelo devuelto por buscar_vuelos (p. ej. DA1234_MADLHR_20261120)"
		},
		"pasajeros": {
			"type": "integer",
			"minimum": 1,
			"maximum": 9,
			"description": "Número de pasajeros para calcular el precio (1 por defecto)"
		},
		"correlationId": {
			"type": "string",
			"description": "Identificador de trazabilidad de la petición. Opcional: si la solicitud trae un correlationId, cópialo tal cual"
		}
	},
	"required": [
		"vueloId"
	]
}
